from __future__ import annotations

from dataclasses import asdict, dataclass
from typing import Literal


MetricClass = Literal["SOURCE", "DERIVED", "MODEL", "UNAVAILABLE"]
StatusRole = Literal["CORE", "SUPPORTING", "INFORMATIONAL", "CONDITIONAL"]
ImplementationState = Literal["CURRENT", "DETERMINISTIC_WIRING", "MODEL_LOGIC", "CONTEXT_REQUIRED", "NEW_INGESTION"]


@dataclass(frozen=True)
class ResearchMetric:
    key: str
    section: str
    label: str
    classification: MetricClass
    source_tables: tuple[str, ...]
    source_columns: tuple[str, ...]
    providers: tuple[str, ...]
    formula: str
    required_inputs: tuple[str, ...]
    freshness_policy: str
    null_behavior: str
    evidence_type: str
    status_role: StatusRole
    implementation_state: ImplementationState
    current_path: str | None = None

    def payload(self) -> dict[str, object]:
        return asdict(self)


def metric(
    key: str, section: str, label: str, classification: MetricClass,
    tables: str, columns: str, providers: str, formula: str, inputs: str,
    freshness: str, null_behavior: str, evidence: str, role: StatusRole,
    state: ImplementationState, current_path: str | None = None,
) -> ResearchMetric:
    split = lambda value: tuple(item.strip() for item in value.split("|") if item.strip())
    return ResearchMetric(key, section, label, classification, split(tables), split(columns), split(providers),
                          formula, split(inputs), freshness, null_behavior, evidence, role, state, current_path)


MARKET_FRESH = "Current session when entitled; otherwise latest completed session, stale after 2 trading days."
FUND_FRESH = "Latest filed comparable period; stale after 120 days for quarterly issuers or 400 days for FY-only data."
NEWS_FRESH = "Rolling 30 days; stale when no qualifying article exists in 30 days."
EVENT_FRESH = "Future confirmed event; revalidate daily and mark stale after its scheduled time."
PORTFOLIO_FRESH = "Latest saved portfolio/read model; stale when holdings version or source prices advance."
NULL = "Return null and render the named UNAVAILABLE/PARTIAL state; never substitute zero or a neutral score."


