SECTION_STATUS_POLICY = {
    "SUCCESS": "Every CORE metric is non-null, fresh, and successful; supporting gaps may remain explicit.",
    "PARTIAL": "At least one CORE metric is usable, but another CORE metric is null, stale, failed, or context-blocked.",
    "UNAVAILABLE": "No CORE metric is usable for the section.",
    "FAILED": "A required source or deterministic calculation errored; existing stale evidence may still be shown separately.",
}


def registry_payload() -> dict[str, object]:
    return {
        "version": "research-metric-registry-v1",
        "classification_definitions": {
            "SOURCE": "Directly stored provider/user value with no analytical transformation beyond normalization.",
            "DERIVED": "Deterministic calculation whose exact formula and required inputs are disclosed.",
            "MODEL": "Scenario, interpretation, ranking, or opinion output; never presented as verified fact.",
            "UNAVAILABLE": "No defensible existing EagleEyes source or approved calculation path.",
        },
        "section_status_policy": SECTION_STATUS_POLICY,
        "metrics": [item.payload() for item in REGISTRY],
    }
